package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;
import java.util.function.Function;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;

/** What is due on a claim, read from the rates its person's grade has. */
@Component
public class Dues {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final ClaimRepository claims;

    public Dues(RateRepository rates, SheetRepository sheets, ClaimRepository claims) {
        this.rates = rates;
        this.sheets = sheets;
        this.claims = claims;
    }

    /**
     * What a claim's figures are read against: the sheet (its today and its dated settings; null when
     * not found), the sheet's rates, and how the claim a correction names is found.
     */
    public record Basis(Sheet sheet, List<Rate> rates, Function<Claim, Optional<Claim>> corrected) {

        /** The rate in force for a grade on a date (see {@link RateRepository#findInForce}). */
        public Optional<Rate> rateInForce(String grade, LocalDate date) {
            return RateRepository.inForce(rates, grade, date);
        }

        LocalDate today() {
            return sheet == null ? null : sheet.getToday();
        }
    }

    /** The sheet as the store holds it now: what every live figure is read against. */
    public Basis live(String sheetId) {
        return new Basis(sheets.findById(sheetId).orElse(null), rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId),
                claim -> claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects()));
    }

    /**
     * How a claim's live figures round: by the sheet's policy date against the claim's date, or for a
     * correction the date of the claim it corrects (its own when that claim is not found).
     */
    private RoundingMode rounding(Claim claim, Basis basis) {
        LocalDate date = claim.getDate();
        if (claim.getCorrects() != null) {
            date = basis.corrected().apply(claim).map(Claim::getDate).orElse(date);
        }
        Sheet sheet = basis.sheet();
        return sheet == null ? RoundingMode.HALF_EVEN : sheet.roundingOn(date);
    }

    /**
     * The due figure a claim shows, before its late charge and floor: the one fixed when it was settled,
     * else (unless it is PENDING, which is not bound) the rate figure its person's last statement bound it
     * to, else its amount at the rate the grade has in force on the claim's date; null (n/a) when there is none.
     */
    public BigDecimal figure(Claim claim, String grade) {
        return figure(claim, grade, live(claim.getSheetId()));
    }

    /** The due figure a claim shows (see {@link #figure(Claim, String)}), read against a basis. */
    public BigDecimal figure(Claim claim, String grade, Basis basis) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : live(claim, grade, basis);
    }

    /**
     * The due a claim shows: the greater of the floor in force on its date and its figure (see
     * {@link #figure}) with the late charge on top while it is overdue; a settled claim's figure is
     * frozen as it was settled. Null (n/a) when it has no figure.
     */
    public BigDecimal due(Claim claim, String grade) {
        return due(claim, grade, live(claim.getSheetId()));
    }

    /** The due a claim shows (see {@link #due(Claim, String)}), read against a basis. */
    public BigDecimal due(Claim claim, String grade, Basis basis) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return floored(claim, withLate(claim, grade, figure(claim, grade, basis), basis), basis);
    }

    /**
     * The due a claim is settled at: the figure a statement bound it to, else its live figure, with
     * the late charge it has on the sheet's today on top; null when it has no figure.
     */
    public BigDecimal settling(Claim claim, String grade) {
        Basis basis = live(claim.getSheetId());
        return floored(claim, withLate(claim, grade, claim.isStated() ? claim.getStatedDue() : live(claim, grade, basis), basis), basis);
    }

    /**
     * The due a PENDING claim is approved at: its live figure (a statement does not bind it while
     * PENDING) with the late charge it has on the sheet's today on top; null when it has no figure.
     */
    public BigDecimal approving(Claim claim, String grade) {
        Basis basis = live(claim.getSheetId());
        return floored(claim, withLate(claim, grade, live(claim, grade, basis), basis), basis);
    }

    /**
     * The due a SETTLED claim is re-settled at: what it would show today as an OPEN claim bound by no
     * statement, its live figure with the late charge it would have on the sheet's today on top; null
     * when it has no figure.
     */
    public BigDecimal resettling(Claim claim, String grade) {
        Basis basis = live(claim.getSheetId());
        BigDecimal figure = live(claim, grade, basis);
        return figure == null || claim.isCorrection() ? figure : floored(claim, lateOn(claim, grade, figure, basis), basis);
    }

    /**
     * A figure with the claim's late charge on top while an OPEN or PENDING claim is past its due-by
     * (fixed when it was added) on the sheet's today (see {@link #lateOn}), rounded by the claim's date
     * against the policy date. The charge is never bound: it always follows the sheet's today.
     * A correction has no late charge, nor has a claim deferred on the sheet's today (it is not overdue).
     */
    private BigDecimal withLate(Claim claim, String grade, BigDecimal figure, Basis basis) {
        if (figure == null || claim.isCorrection() || !claim.getStatus().isOpen() || claim.getSettledDue() != null) {
            return figure;
        }
        if (basis.sheet() != null && claim.isDeferredOn(basis.today())) {
            return figure;
        }
        return lateOn(claim, grade, figure, basis);
    }

    /**
     * A figure with the late charge an OPEN claim would have on the sheet's today on top: for every full
     * 30 days past its due-by plus its grade's grace (see {@link Sheet#lateFrom}), the late percent in
     * force on that boundary date (that date plus 30, 60, 90 ... days) of the figure plus the charges of
     * the boundaries before it (the charge compounds), rounded like the claim, the charges added up.
     */
    private BigDecimal lateOn(Claim claim, String grade, BigDecimal figure, Basis basis) {
        Sheet sheet = basis.sheet();
        if (sheet == null) {
            return figure;
        }
        LocalDate dueBy = sheet.lateFrom(claim.getDueBy(), grade, claim.getDate());
        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / 30;
        RoundingMode rounding = rounding(claim, basis);
        BigDecimal late = BigDecimal.ZERO.setScale(2);
        for (long period = 1; period <= periods; period++) {
            BigDecimal latePct = sheet.latePctOn(dueBy.plusDays(30 * period));
            if (latePct != null && latePct.signum() != 0) {
                late = late.add(figure.add(late).multiply(latePct).movePointLeft(2).setScale(2, rounding));
            }
        }
        return figure.add(late);
    }

    /**
     * A due raised to the floor in force on the claim's date when below it, applied last (after the
     * late charge); a correction has no floor, and null (n/a) stays null.
     */
    private BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
        if (due == null || claim.isCorrection()) {
            return due;
        }
        Sheet sheet = basis.sheet();
        BigDecimal floor = sheet == null ? null : sheet.floorOn(claim.getDate());
        return floor != null && due.compareTo(floor) < 0 ? floor : due;
    }

    /**
     * A claim's rate figure: its amount at the rate the grade has in force on the claim's date, rounded
     * by the claim's date against the policy date, with no floor; null when it has no rate.
     */
    public BigDecimal live(Claim claim, String grade) {
        return live(claim, grade, live(claim.getSheetId()));
    }

    private BigDecimal live(Claim claim, String grade, Basis basis) {
        RoundingMode rounding = rounding(claim, basis);
        return basis.rateInForce(grade, claim.getDate())
                .map(rate -> due(claim.getAmount(), rate, rounding))
                .orElse(null);
    }

    /** What is due on an amount at a rate: the amount times the percent over 100, rounded as given. */
    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (DRAFT
 * when added). A claim with a negative amount is a correction, naming the number of the SETTLED claim
 * of the same person it corrects.
 */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    /**
     * The date the claim is due by: the terms-th business day after its due-from date (see
     * {@link BusinessDays#dueBy}), worked out again when a holiday on or before it is added unless it is SETTLED or VOID.
     */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The terms, in business days, fixed when the claim was added from its person's own terms, else their grade's. */
    @Column(name = "terms", nullable = false)
    private int terms;

    /** The date the claim's terms count from: its date when it was added (a later change of date keeps it). */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The sheet's number given to the claim when opened; null while DRAFT, and kept once VOID. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null otherwise, or when the grade had no rate then. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null until it is opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; null when it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The number of the bulk settle batch that settled the claim; null when not settled by one. */
    @Column(name = "settle_batch")
    private Integer settleBatch;


    /** Whether the claim is bound by its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due figure the claim was bound to by the statement; null when unbound, or when it was n/a. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this one corrects; null unless it is a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's external reference; null when it has none. */
    @Column(name = "ref")
    private String ref;

    /** The reference as compared on the sheet (lower case); null when it has none. */
    @Column(name = "ref_key")
    private String refKey;

    /** The claim's tags, sorted and comma separated; null when it has none. */
    @Column(name = "tags")
    private String tags;

    /** Every tag the claim has ever carried, sorted and comma separated; null when none. */
    @Column(name = "tags_used")
    private String tagsUsed;

    /** The date the claim is deferred until; null when it was never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The number of the claim this one was split from; null unless it was split off another. */
    @Column(name = "split_from")
    private String splitFrom;

    /** How many proofs the claim has; 0 when added. */
    @Column(name = "proofs", nullable = false)
    private int proofs;

    /** The last day (the sheet's today) a reminder was written for the claim; null when never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while a period its date or due-by is in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The reason from the sheet's list the claim was voided with; null when not voided with one. */
    @Column(name = "void_reason")
    private String voidReason;

    /** The claim's status log, oldest first. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id")
    private List<ClaimLogLine> log = new ArrayList<>();

    /** The claim's comments, oldest first. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "claim_id", nullable = false)
    @OrderBy("id")
    private List<ClaimComment> comments = new ArrayList<>();

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, int terms, LocalDate dueBy,
            String note, String corrects) {
        this.terms = terms;
        this.dueFrom = date;
        this.dueBy = dueBy;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public int getTerms() {
        return terms;
    }

    public LocalDate getDueFrom() {
        return dueFrom;
    }

    /** Work the claim's due-by out again against the sheet's holidays now; its terms and due-from are kept. */
    public void workOutDueBy(Set<LocalDate> holidays) {
        this.dueBy = BusinessDays.dueBy(dueFrom, terms, holidays);
    }

    public String getNote() {
        return note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getNumber() {
        return number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    /** Record the user who opened the claim. */
    public void openedBy(String user) {
        this.openedBy = user;
    }

    public String getEditedBy() {
        return editedBy;
    }

    /** Record the user who last edited the claim. */
    public void editedBy(String user) {
        this.editedBy = user;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    /** Record the bulk settle batch that settled the claim. */
    public void settledInBatch(int batch) {
        this.settleBatch = batch;
    }

    /** Whether the user opened or last edited the claim, and so cannot settle or approve it. */
    public boolean isOpenedOrEditedBy(String user) {
        return user.equals(openedBy) || user.equals(editedBy);
    }

    /** Fix the claim's due as it is settled. */
    public void settleDue(BigDecimal due) {
        this.settledDue = due;
    }

    /** Move the claim to a new status; the caller checks the move is allowed. */
    public void become(ClaimStatus status) {
        this.status = status;
    }

    public String getVoidReason() {
        return voidReason;
    }

    /** Record the reason the claim is voided with; null for none. */
    public void voidedWith(String reason) {
        this.voidReason = reason;
    }

    /** Give the claim its number when it is opened; it keeps it from then on. */
    public void number(String number) {
        this.number = number;
    }

    public String getCorrects() {
        return corrects;
    }

    public String getRef() {
        return ref;
    }

    /** Give the claim an external reference; null for none. */
    public void refer(String ref) {
        this.ref = ref;
        this.refKey = keyOf(ref);
    }

    /** The claim's tags, sorted; empty when it has none. */
    public java.util.List<String> getTags() {
        return tags == null ? java.util.List.of() : java.util.List.of(tags.split(","));
    }

    /** Give the claim its tags (see {@link #tagsOf}); empty for none. */
    public void tag(java.util.List<String> tags) {
        this.tags = tags.isEmpty() ? null : String.join(",", tags);
        java.util.List<String> used = java.util.stream.Stream.concat(getTagsUsed().stream(), tags.stream())
                .distinct().sorted().toList();
        this.tagsUsed = used.isEmpty() ? null : String.join(",", used);
    }

    /** Every tag the claim has ever carried, sorted; empty when none. */
    public java.util.List<String> getTagsUsed() {
        return tagsUsed == null ? java.util.List.of() : java.util.List.of(tagsUsed.split(","));
    }

    /**
     * Tags as a comma separated text gives them: each trimmed and lower case, blanks and repeats
     * dropped, sorted.
     */
    public static java.util.List<String> tagsOf(String text) {
        if (text == null) {
            return java.util.List.of();
        }
        return java.util.Arrays.stream(text.split(","))
                .map((t) -> t.trim().toLowerCase(java.util.Locale.ROOT))
                .filter((t) -> !t.isEmpty())
                .distinct()
                .sorted()
                .toList();
    }

    /** A reference as compared on a sheet, without regard to case; null for none. */
    public static String keyOf(String ref) {
        return ref == null ? null : ref.toLowerCase(java.util.Locale.ROOT);
    }

    /** Whether the claim is a correction: its amount is below 0.00. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    /** Change the claim's amount, date, note and the number it corrects. */
    public void change(BigDecimal amount, LocalDate date, String note, String corrects) {
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.corrects = corrects;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to its due figure (null when n/a) as a statement is taken. */
    public void bind(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Move the claim to a new date; its due-by, number and any bound figure are kept. */
    public void redate(LocalDate date) {
        this.date = date;
    }

    /** Move the claim to another person on the sheet. */
    public void reassign(Long personId) {
        this.personId = personId;
    }

    /** Leave the claim unbound, its due live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    /** Defer the claim until a date; the caller checks the deferral is allowed. */
    public void defer(LocalDate until) {
        this.deferredUntil = until;
    }

    /**
     * Whether the claim is deferred on a date (the sheet's today): it is OPEN and the date has not yet
     * reached the date it is deferred until.
     */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    public String getSplitFrom() {
        return splitFrom;
    }

    /**
     * Split an amount off the claim: it keeps the rest of its amount and loses any figure a statement
     * bound it to. The new claim, OPEN with the split-off amount, the same date and note, names this
     * claim's number as the one it was split from; the caller numbers it and records who opened it.
     */
    public Claim split(BigDecimal off, int newTerms, LocalDate newDueBy) {
        Claim split = new Claim(sheetId, personId, off, date, newTerms, newDueBy, note, null);
        split.status = ClaimStatus.OPEN;
        split.splitFrom = number;
        this.amount = amount.subtract(off);
        unbind();
        return split;
    }

    public int getProofs() {
        return proofs;
    }

    /** Raise the claim's proofs count by one; the caller checks the claim can take a proof. */
    public void addProof() {
        proofs++;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    /** Mark the claim reminded on a day; the caller checks the claim can be reminded. */
    public void remind(LocalDate on) {
        this.remindedOn = on;
    }

    public String getLockedBy() {
        return lockedBy;
    }

    /** Whether the claim was added while a period its date or due-by is in was soft-closed. */
    public boolean isLateEntry() {
        return lateEntry;
    }

    /** Mark the claim as added while its period was soft-closed. */
    public void markLateEntry() {
        this.lateEntry = true;
    }

    /** Whether an editor of a user other than this one holds the claim. */
    public boolean isLockedAgainst(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** Lock the claim for the user's editor (null: release it); the caller checks the lock is theirs to take. */
    public void lockFor(String user) {
        this.lockedBy = user;
    }

    public List<ClaimComment> getComments() {
        return List.copyOf(comments);
    }

    /** Add a comment to the claim, by the user on the sheet's today. */
    public void comment(String by, LocalDate on, String text) {
        comments.add(new ClaimComment(by, on, text));
    }

    public List<ClaimLogLine> getLog() {
        return List.copyOf(log);
    }

    /**
     * The status the claim had at the end of a day, as its status log records it: the last line dated
     * on or before it, or null when the claim was added after it. A claim with no log (added before
     * the log) has its current status.
     */
    public ClaimStatus statusAt(LocalDate day) {
        if (log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogLine line : log) {
            if (!line.getOn().isAfter(day)) {
                then = line.getStatus();
            }
        }
        return then;
    }

    /**
     * The day the claim was last settled, as its status log records it: the date of its last SETTLED
     * line, or null when the log has none.
     */
    public LocalDate settledOn() {
        LocalDate on = null;
        for (ClaimLogLine line : log) {
            if (line.getStatus() == ClaimStatus.SETTLED) {
                on = line.getOn();
            }
        }
        return on;
    }

    /** Add a line to the claim's status log for the status it now has. */
    public void logged(String by, LocalDate on, BigDecimal due) {
        log.add(new ClaimLogLine(status, by, on, due));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT,
 * OPEN or PENDING one voided. An OPEN claim a clerk settles above the clerk limit goes PENDING, which
 * a steward approves (SETTLED) or rejects (back to OPEN). A steward may void a SETTLED claim within
 * {@link #VOID_SETTLED_DAYS} days of its settlement; VOID is final. Only OPEN, PENDING and SETTLED
 * claims count.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The days after its settlement (by the sheet's today) a SETTLED claim may still be voided. */
    public static final int VOID_SETTLED_DAYS = 7;

    /** Whether a claim may move from this status to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/** Business days: every day that is not a Saturday, a Sunday or a holiday on the sheet. */
public final class BusinessDays {

    private BusinessDays() {
    }

    /** Whether a day is a business day, given the sheet's holidays. */
    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
        DayOfWeek weekday = day.getDayOfWeek();
        return weekday != DayOfWeek.SATURDAY && weekday != DayOfWeek.SUNDAY && !holidays.contains(day);
    }

    /**
     * The date a claim is due by: the terms-th business day after a date, counting forward from the day
     * after it; the date itself for terms of 0.
     */
    public static LocalDate dueBy(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate day = date;
        for (int counted = 0; counted < terms; ) {
            day = day.plusDays(1);
            if (isBusinessDay(day, holidays)) {
                counted++;
            }
        }
        return day;
    }
}

