462	    /**
463	     * Re-settle a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
464	     * claim bound by no statement (today's rates, grades, floor and late charge). Only a steward
465	     * re-settles; refused when the claim is not SETTLED or is due by inside a closed period.
466	     */
467	    @Transactional
468	    public Claim resettle(String sheetId, String user, long claimId) {
469	        sheets.lock(sheetId);
470	        Rollups.Rollup before = rollups.take(sheetId);
471	        Claim claim = claim(sheetId, claimId);
472	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
473	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
474	        }
475	        if (claim.getStatus() != ClaimStatus.SETTLED) {
476	            throw new ResponseStatusException(HttpStatus.CONFLICT,
477	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
478	        }
479	        periods.refuseIfClosed(sheetId, claim.getDueBy());
480	        Person person = person(sheetId, claim.getPersonId());
481	        BigDecimal old = claim.getSettledDue();
482	        claim.settleDue(dues.resettling(claim, person.gradeOn(claim.getDate())));
483	        Claim saved = logged(claims.saveAndFlush(claim), user, person);
484	        audited("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
485	                " old=" + (old != null ? old.toPlainString() : NO_RATE)
486	                        + " new=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE));
487	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
488	        rollups.audit(sheetId, user, before);
489	        return saved;
490	    }
491	
492	    /**
493	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by its person's last
494	     * statement when that statement included it. Only a steward rejects.
495	     */
496	    @Transactional
497	    public Claim reject(String sheetId, String user, long claimId, String reason) {
498	        sheets.lock(sheetId);
499	        Rollups.Rollup before = rollups.take(sheetId);
500	        Claim claim = pending(sheetId, user, claimId);
501	        claim.become(ClaimStatus.OPEN);
502	        Claim saved = logged(claims.saveAndFlush(claim), user, person(sheetId, claim.getPersonId()));
503	        audited("CLAIM_REJECTED", sheetId, user, person(sheetId, saved.getPersonId()), saved, saved.getNumber(),
504	                " reason=" + reason.trim());
505	        rollups.audit(sheetId, user, before);
506	        return saved;
507	    }
