556	    /**
557	     * Re-date an OPEN or PENDING claim: it keeps the due-by fixed when it was added, and so its period
558	     * and number, and any figure a statement bound it to. Only a steward re-dates; refused when the claim
559	     * is not OPEN or PENDING, when its due-by is inside a closed period, or when the new date is after
560	     * its person's retirement.
561	     */
562	    @Transactional
563	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
564	        sheets.lock(sheetId);
565	        Rollups.Rollup before = rollups.take(sheetId);
566	        Claim claim = claim(sheetId, claimId);
567	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
568	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim.");
569	        }
570	        if (!claim.getStatus().isOpen()) {
571	            throw new ResponseStatusException(HttpStatus.CONFLICT,
572	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can.");
573	        }
574	        periods.refuseIfClosed(sheetId, claim.getDueBy());
575	        Person person = person(sheetId, claim.getPersonId());
576	        refuseIfRetired(person, date);
577	        LocalDate old = claim.getDate();
578	        claim.redate(date);
579	        Claim saved = claims.saveAndFlush(claim);
580	        audited("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
581	        rollups.audit(sheetId, user, before);
582	        return saved;
583	    }
