585	    /** What a split did: the original claim, as it is now, and the new claim split off it. */
586	    public record Split(Claim original, Claim split) {
587	    }
588	
589	    /**
590	     * Split an amount (above 0.00 and below the claim's amount) off an OPEN claim: it keeps the rest
591	     * of its amount and loses any figure a statement bound it to; a new OPEN claim with the split-off
592	     * amount, the same date and note, the next number, opened by the user and due by a date fixed now
593	     * from the terms in force on its date, names the original's number as the one it was split from;
594	     * it is a late entry when that due-by is inside a soft-closed period. Refused when the claim is not
595	     * OPEN, is deferred on the sheet's today, or when its due-by or the new claim's is inside a closed
596	     * period.
597	     */
598	    @Transactional
599	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
600	        Sheet sheet = sheets.lock(sheetId);
601	        LocalDate today = sheet.getToday();
602	        Rollups.Rollup before = rollups.take(sheetId);
603	        Claim claim = claim(sheetId, claimId);
604	        if (claim.getStatus() != ClaimStatus.OPEN) {
605	            throw new ResponseStatusException(HttpStatus.CONFLICT,
606	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can.");
607	        }
608	        if (claim.isDeferredOn(today)) {
609	            throw new ResponseStatusException(HttpStatus.CONFLICT,
610	                    "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be split.");
611	        }
612	        periods.refuseIfClosed(sheetId, claim.getDueBy());
613	        BigDecimal off = money(amount);
614	        if (off.signum() <= 0 || off.compareTo(claim.getAmount()) >= 0) {
615	            throw new ResponseStatusException(HttpStatus.CONFLICT,
616	                    "The amount split off must be above 0.00 and below the claim's " + claim.getAmount().toPlainString() + ".");
617	        }
618	        Person person = person(sheetId, claim.getPersonId());
619	        int terms = terms(sheet, person, claim.getDate());
620	        LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), terms);
621	        periods.refuseIfClosed(sheetId, dueBy);
622	        Claim split = claim.split(off, terms, dueBy);
623	        if (periods.softClosedOn(sheetId, dueBy)) {
624	            split.markLateEntry();
625	        }
626	        split.number(periods.nextClaimNumber(sheetId, split.getDueBy()));
627	        split.openedBy(user);
628	        Claim original = claims.saveAndFlush(claim);
629	        split = logged(claims.saveAndFlush(split), user, person);
630	        audited("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
631	        audited("CLAIM_OPENED", sheetId, user, person, split);
632	        rollups.audit(sheetId, user, before);
633	        return new Split(original, split);
634	    }
