636	    /**
637	     * The PENDING claim a steward approves or rejects; refused when it is not PENDING, when its date
638	     * is inside a closed period, or when the user is not a steward.
639	     */
640	    private Claim pending(String sheetId, String user, long claimId) {
641	        Claim claim = claim(sheetId, claimId);
642	        periods.refuseIfClosed(sheetId, claim.getDueBy());
643	        if (claim.getStatus() != ClaimStatus.PENDING) {
644	            throw new ResponseStatusException(HttpStatus.CONFLICT,
645	                    "A " + claim.getStatus() + " claim is not pending approval.");
646	        }
647	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
648	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
649	        }
650	        return claim;
651	    }
