653	    /**
654	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force
655	     * on the claim's date: its person's grade's (the grade in force then) when one is set, else the
656	     * sheet's (a due of n/a is within any threshold).
657	     */
658	    private void refuseUnproved(String sheetId, Claim claim, String grade, BigDecimal due) {
659	        BigDecimal threshold = sheets.load(sheetId).proofThresholdFor(grade, claim.getDate());
660	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
661	            throw new ResponseStatusException(HttpStatus.CONFLICT,
662	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
663	                            + ": it needs a proof before it is settled.");
664	        }
665	    }
666	
667	    /**
668	     * Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
669	     * on the claim's date (a due of n/a is within any threshold).
670	     */
671	    private void refuseUnnoted(String sheetId, Claim claim, BigDecimal due) {
672	        BigDecimal threshold = sheets.load(sheetId).noteThresholdOn(claim.getDate());
673	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
674	                && due.compareTo(threshold) > 0) {
675	            throw new ResponseStatusException(HttpStatus.CONFLICT,
676	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
677	                            + ": it needs a note before it is opened.");
678	        }
679	    }
680	
681	    /**
682	     * Refuse voiding a SETTLED claim unless the user acts as a steward and the sheet's today is no more
683	     * than {@link ClaimStatus#VOID_SETTLED_DAYS} days after the claim's settlement in its status log.
684	     */
685	    private void refuseVoidingSettled(String sheetId, String user, Claim claim, LocalDate today) {
686	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
687	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a SETTLED claim.");
688	        }
689	        LocalDate settledOn = claim.settledOn();
690	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
691	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A SETTLED claim can only be voided within "
692	                    + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
693	        }
694	    }
695	
696	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit. */
697	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
698	        BigDecimal limit = sheets.clerkLimit(sheetId);
699	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
700	            return false;
701	        }
702	        return Role.CLERK.equals(roles.roleOf(sheetId, user));
703	    }
704	
705	    /**
706	     * Refuse a correction (an amount below 0.00) unless it names, by number, a SETTLED claim of the
707	     * same person; and refuse naming a claim to correct on any other claim.
708	     */
709	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
710	        if (amount.signum() >= 0) {
711	            if (corrects != null) {
712	                throw new ResponseStatusException(HttpStatus.CONFLICT,
713	                        "Only a correction, with an amount below 0.00, names a claim it corrects.");
714	            }
715	            return;
716	        }
717	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
718	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
719	                .isPresent();
720	        if (!settled) {
721	            throw new ResponseStatusException(HttpStatus.CONFLICT,
722	                    "A correction must name the number of a SETTLED claim of the same person.");
723	        }
724	    }
