726	    /** Refuse a claim dated after its person's retirement. */
727	    private static void refuseIfRetired(Person person, LocalDate date) {
728	        if (!person.canClaimOn(date)) {
729	            throw new ResponseStatusException(HttpStatus.CONFLICT,
730	                    person.getName() + " is retired from " + person.getRetiredFrom() + ": a claim cannot be dated after it.");
731	        }
732	    }
