740	     * The terms, in business days, a claim of the person dated on a date is fixed with: the first of the
741	     * person's own terms, their grade's terms and the sheet's terms in force on it.
742	     */
743	    private static int terms(Sheet sheet, Person person, LocalDate date) {
744	        Integer own = person.getTerms();
745	        return own != null ? own : sheet.termsFor(person.gradeOn(date), date);
