754	     * Add a line to the claim's status log for the status it now has: by the user, on the sheet's
755	     * today, with its due as computed now.
756	     */
757	    private Claim logged(Claim claim, String user, Person person) {
758	        claim.logged(user, sheets.today(claim.getSheetId()), dues.due(claim, person.gradeOn(claim.getDate())));
759	        return claims.saveAndFlush(claim);
