784	    /** Refuse a reference already used on the sheet by a claim other than the one given (null: any). */
785	    private void refuseIfReferred(String sheetId, String ref, Long self) {
786	        if (ref == null) {
787	            return;
788	        }
789	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
790	                .filter((other) -> !other.getId().equals(self))
