package net.officefloor.hq.app.period;


/**
 * A period on a sheet: a name, unique on the sheet ignoring case by its {@link #keyOf key}, and a
 * from and to date, both inclusive. No two periods on a sheet overlap. A closed period keeps the
 * due-total it had when it was closed, and each person's due-total for it then, until it is reopened.
 * A soft-closed period fixes them the same way, but claims due by in it can still change; it can be
 * closed (fixing them afresh) or reopened.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures fixed, its claims still open to change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Each person's due-total for the period fixed when it was closed, by person id; empty while open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** The last number the period gave a claim opened in it under period numbering; 0 before any. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = clean(name);
        this.nameKey = keyOf(name);
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    /** The name as it is kept: surrounding spaces removed. */
    public static String clean(String name) {
        return name.trim();
    }

    /** The key a name is unique by on its sheet: kept as cleaned, ignoring case. */
    public static String keyOf(String name) {
        return clean(name).toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean isFixed() {
        return closed || softClosed;
    }

    /** The due-total fixed when the period was closed; null while it is open. */
    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    /** Close the period, fixing each person's due-total for it and its own, their sum. */
    public void close(Map<Long, BigDecimal> totals) {
        fixTotals(totals);
        this.closed = true;
        this.softClosed = false;
    }

    /** Soft-close the period, fixing its figures as a close does while its claims stay open to change. */
    public void softClose(Map<Long, BigDecimal> totals) {
        fixTotals(totals);
        this.softClosed = true;
    }

    private void fixTotals(Map<Long, BigDecimal> totals) {
        this.personTotals.clear();
        this.personTotals.putAll(totals);
        this.closedTotal = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
    }

    /** Whether the date falls inside this period (inclusive). */
    public boolean contains(LocalDate date) {
        return !fromDate.isAfter(date) && !toDate.isBefore(date);
    }

    /** Whether this period shares any day with the inclusive range {@code from} to {@code to}. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !toDate.isBefore(from);
    }

    /** Give out the period's next claim number: 1 for the first, then 2, and so on. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }
}
package net.officefloor.hq.app.period;


/** The periods on a sheet: listed, added, closed and reopened. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final SheetService sheets;
    private final RoleService roles;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, ClaimRepository claims, PersonRepository people, Dues dues,
            SheetService sheets, RoleService roles, Audit audit) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.sheets = sheets;
        this.roles = roles;
        this.audit = audit;
    }

    /** The sheet's periods by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    /**
     * Add a period to the sheet; refused when its from-date is after its to-date, when its name is
     * already in use on the sheet, or when it shares a day with another period.
     */
    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        // Take the sheet's lock first, so two periods added at once cannot both pass the checks.
        sheets.lock(sheetId);
        if (from.isAfter(to)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's from-date cannot be after its to-date.");
        }
        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another period on this sheet.");
        }
        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to));
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
                + " from=" + period.getFromDate() + " to=" + period.getToDate());
        return period;
    }

    /**
     * Generate one period per calendar month from the from-date's month to the to-date's month, each
     * running from the first to the last day of its month and named yyyy-mm, in month order. A month
     * whose name is already a period on the sheet, or whose days overlap one, is left out and the others
     * are still made. Refused when the to-date is before the from-date.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        // Take the sheet's lock first, so no period added meanwhile slips past the checks.
        sheets.lock(sheetId);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
        }
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (existing.stream().anyMatch(p -> p.getName().toLowerCase(Locale.ROOT).equals(Period.keyOf(name))
                    || p.overlaps(first, last))) {
                continue;
            }
            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
            existing.add(period);
            made.add(period);
            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
                    + " from=" + period.getFromDate() + " to=" + period.getToDate());
        }
        return made;
    }

    /**
     * Close a period, fixing at this moment each person's due-total for it and its own, their sum. A person's is the sum of the due figures,
     * as computed now, of the claims due by in it that were OPEN, PENDING or SETTLED at the end of its last day by their status log, each at
     * the grade its person has in force on its date (a claim with no figure adds nothing), leaving out those still OPEN or PENDING and dated
     * within their person's hold or of a person whose retirement date is reached, unless bound by a statement, and those deferred on today. A soft-closed period closes with its figures
     * fixed afresh. Refused when the period is already closed, or for a role the sheet's permission matrix does not allow.
     */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        // Take the sheet's lock first, so no claim in the period changes while its total is fixed.
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (!roles.permits(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
        }
        if (period.isClosed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
        }
        return fix(sheetId, user, period, today, "");
    }

    /**
     * Soft-close an open period: its due-total and each person's figure for it are fixed as on a close
     * (see {@link #close}), while claims due by in it can still be added and changed. Refused when the
     * period is already closed or soft-closed, or for a role the sheet's permission matrix does not
     * allow to close.
     */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (!roles.permits(sheetId, user, "close")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
        }
        if (period.isFixed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed or soft-closed.");
        }
        period.softClose(totals(sheetId, period, today));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString());
        return saved;
    }

    /**
     * The sheet's today was changed: close, in order of their to-dates, each open period whose to-date
     * plus the sheet's grace days is before the new today, exactly as a close by hand would, its
     * PERIOD_CLOSED marked auto=yes. A soft-closed period keeps the figures fixed for it and is left as
     * it is. Nothing closes while the grace days are off.
     */
    @EventListener
    public void todayChanged(TodayChanged change) {
        if (change.graceDays() == null) {
            return;
        }
        LocalDate today = sheets.lock(change.sheetId()).getToday();
        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(change.sheetId()).stream()
                .filter(p -> !p.isFixed() && p.getToDate().plusDays(change.graceDays()).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .toList();
        for (Period period : due) {
            fix(change.sheetId(), change.user(), period, today, " auto=yes");
        }
    }

    /** Close an open or soft-closed period, fixing its totals as of today, and audit it with the given trailing fields. */
    private Period fix(String sheetId, String user, Period period, LocalDate today, String trailing) {
        period.close(totals(sheetId, period, today));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString() + trailing);
        return saved;
    }

    /** Each person's due-total for the period as of today, by person id (see {@link #close}). */
    private Map<Long, BigDecimal> totals(String sheetId, Period period, LocalDate today) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, person -> person));
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !period.contains(claim.getDueBy())) {
                continue;
            }
            ClaimStatus then = claim.statusAt(period.getToDate());
            if (then == null || !then.counts() || claim.isDeferredOn(today)
                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(claim.getDate(), today))) {
                continue;
            }
            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) {
                totals.merge(person.getId(), figure, BigDecimal::add);
            }
        }
        return totals;
    }

    /**
     * Reopen a closed or soft-closed period: its due-total is live again, the claims due by in it counting at their
     * current figures. Refused for a role the sheet's permission matrix
     * does not allow (anyone but a steward by default), and when the period is neither closed nor soft-closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        LocalDate today = sheets.lock(sheetId).getToday();
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
        if (!roles.permits(sheetId, user, "reopen")) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period.");
        }
        if (!period.isFixed()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /**
     * Give out the number for a claim due by a date (its due-by) as it is opened, holding the sheet's lock until
     * the caller's transaction ends. While the sheet numbers by period (see {@link Sheet#numbersByPeriod})
     * it is the next within the period the date falls in, {@code <period name>-<n>}, or {@code X-<n>}
     * when it falls in none; otherwise it is the sheet's next sheet-wide number.
     */
    @Transactional
    public String nextClaimNumber(String sheetId, LocalDate date) {
        Sheet sheet = sheets.lock(sheetId);
        if (!sheet.numbersByPeriod()) {
            return String.valueOf(sheet.nextClaimNumber());
        }
        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> p.contains(date))
                .findFirst()
                .map(p -> p.getName() + "-" + p.nextClaimNumber())
                .orElseGet(() -> "X-" + sheet.nextUnperiodClaimNumber());
    }

    /** The name of the period a date falls in on the sheet; null when it falls in none. */
    @Transactional(readOnly = true)
    public String periodOn(String sheetId, LocalDate date) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .filter(p -> p.contains(date))
                .findFirst()
                .map(Period::getName)
                .orElse(null);
    }

    /** Whether the date falls inside one of the sheet's soft-closed periods. */
    @Transactional(readOnly = true)
    public boolean softClosedOn(String sheetId, LocalDate date) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .anyMatch(p -> p.isSoftClosed() && p.contains(date));
    }

    /** Refuse a change to a claim due by a date (its due-by) inside one of the sheet's closed periods. */
    public void refuseIfClosed(String sheetId, LocalDate date) {
        if (periods.findBySheetIdAndClosedTrue(sheetId).stream().anyMatch(p -> p.contains(date))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is due by inside a closed period.");
        }
    }
}
package net.officefloor.hq.app.statement;


/**
 * A person's statements: taking one records their due-total on the sheet's today (or a date before it), binds each of
 * their counting claims to the due figure it shows then, and leaves the rest unbound. A steward may
 * cancel the last one: the claims it bound are live again, and the person shows the one before it.
 */
@Service
public class StatementService {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** The person as stated, with all of their claims, newest first. */
    public record Stated(Person person, List<Claim> claims) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;
    private final SheetHistory history;
    private final SheetService sheets;
    private final Rollups rollups;
    private final StatementRepository statements;
    private final RoleService roles;
    private final Audit audit;

    public StatementService(PersonRepository people, ClaimRepository claims, Dues dues, SheetHistory history,
            SheetService sheets, Rollups rollups, StatementRepository statements, RoleService roles, Audit audit) {
        this.rollups = rollups;
        this.statements = statements;
        this.roles = roles;
        this.people = people;
        this.claims = claims;
        this.dues = dues;
        this.history = history;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * Take a statement for a person on the sheet, as of a date on or before the sheet's today (null:
     * now). Their claims that counted at the end of that date are bound to the figures they had then,
     * every change made while the sheet's today was after it left out and that date standing in for
     * the sheet's today; every other claim of theirs is left unbound. Refused for a date after the
     * sheet's today, or one the sheet or the person was not yet kept on.
     */
    @Transactional
    public Stated take(String sheetId, String user, long personId, LocalDate asOf) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (asOf != null && asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A statement cannot be taken as of a date after today.");
        }
        LocalDate day = asOf != null ? asOf : today;
        // On the sheet's today every change counts: the sheet as it stands now. Before it, as kept then.
        Person then;
        // Their claims as they stood then, by id.
        Map<Long, Claim> theirsThen = new LinkedHashMap<>();
        Dues.Basis basis;
        Sheet sheet;
        if (day.equals(today)) {
            then = person;
            claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).forEach(c -> theirsThen.put(c.getId(), c));
            basis = dues.live(sheetId);
            sheet = sheets.load(sheetId);
        } else {
            SheetHistory.AsOf kept = history.at(sheetId, day).orElseThrow(() -> notYet(day));
            then = kept.people().get(personId);
            if (then == null) {
                throw notYet(day);
            }
            kept.claims().forEach((id, c) -> {
                if (c.getPersonId() == personId) {
                    theirsThen.put(id, c);
                }
            });
            basis = kept.basis();
            sheet = kept.sheet();
        }
        Rollups.Rollup before = rollups.take(sheetId);
        Map<Long, BigDecimal> bound = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Map.Entry<Long, Claim> entry : theirsThen.entrySet()) {
            Claim claim = entry.getValue();
            // As in the live totals: an OPEN or PENDING claim dated within a hold, or of a person whose
            // retirement date is reached, and not bound, is left
            // out, as is a claim deferred on the day.
            if (!then.countsLive(claim.getStatus(), claim.getDate(), claim.isStated(), claim.isDeferredOn(day), day)) {
                continue;
            }
            // The statement binds the rate figure; the late charge and floor stay live, but count in its total.
            BigDecimal figure = dues.figure(claim, then.gradeOn(claim.getDate()), basis);
            figured |= figure != null;
            bound.put(entry.getKey(), figure);
            counted++;
            BigDecimal due = dues.due(claim, then.gradeOn(claim.getDate()), basis);
            if (due != null) {
                total = total.add(due);
            }
        }
        // As on the screen: n/a when the grade in force on the day has no rate, unless a claim has a figure.
        if (basis.rateInForce(then.gradeOn(day), day).isEmpty() && !figured) {
            total = null;
        }
        // A due-total is at most the cap in force on the day. The claims they have now are bound by id.
        total = sheet.capped(total);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        for (Claim claim : theirs) {
            if (bound.containsKey(claim.getId())) {
                claim.bind(bound.get(claim.getId()));
            } else {
                claim.unbind();
            }
        }
        person.stated(total, day);
        Person saved = people.saveAndFlush(person);
        statements.saveAndFlush(new Statement(sheetId, saved.getId(), saved.getStatementCount(), total, day));
        List<Claim> stated = claims.saveAllAndFlush(theirs);
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted
                + (asOf != null ? " asof=" + asOf : ""));
        rollups.audit(sheetId, user, before);
        return new Stated(saved, stated);
    }

    /** Refused: the sheet, or the person, was not yet kept at the end of that date. */
    private static ResponseStatusException notYet(LocalDate day) {
        return new ResponseStatusException(HttpStatus.CONFLICT, "The person was not on the sheet on " + day + ".");
    }

    /**
     * Cancel a person's last statement: the claims it bound are live again (a figure an earlier
     * statement bound is not restored), and the person shows the statement before it, or none. Only a
     * steward cancels; refused when the person has no statement.
     */
    @Transactional
    public Stated cancel(String sheetId, String user, long personId) {
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement.");
        }
        if (person.getStatementCount() == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal cancelled = person.getStatementTotal();
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, personId);
        if (!taken.isEmpty() && taken.get(0).getSeq() == person.getStatementCount()) {
            statements.delete(taken.remove(0));
        }
        // The one before it, when it was recorded.
        Statement previous = taken.isEmpty() || taken.get(0).getSeq() != person.getStatementCount() - 1
                ? null : taken.get(0);
        person.unstated(previous == null ? null : previous.getTotal(), previous == null ? null : previous.getTakenOn());
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        theirs.forEach(Claim::unbind);
        Person saved = people.saveAndFlush(person);
        List<Claim> live = claims.saveAllAndFlush(theirs);
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (cancelled != null ? cancelled.toPlainString() : NO_RATE));
        rollups.audit(sheetId, user, before);
        return new Stated(saved, live);
    }
}

