    private final Audit audit;
    private final ApplicationEventPublisher events;

    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit, ApplicationEventPublisher events) {
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
        this.events = events;
    }

    /** Load a sheet; a new sheet's today starts as the real date. */
    @Transactional
    public synchronized Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
    }

    /**
     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
     * this, never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /**
     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
     * the sheet's other rows before writing are made one at a time.
     */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findLockedById(id).orElseThrow();
    }

    /**
     * Change the sheet's today, auditing the figures that moves. When it moves, each person's due-total
     * as it stood on the day being left is audited first, in list order, and the sheet as it stood at
     * the end of that day is kept (see {@link TodayLeaving}). The periods it puts past their grace
     * days are closed (see {@link TodayChanged}) before those figures are audited.
     */
    @Transactional
    public synchronized Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollups.Rollup before = rollups.take(id);
        if (!today.equals(sheet.getToday())) {
            before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
                    + " name=" + figures.name() + " due-total=" + Rollups.shown(figures.dueTotal())));
            events.publishEvent(new TodayLeaving(id, sheet.getToday()));
        }
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today, saved.getGraceDays()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Whether the sheet is archived: nothing on it may change. */
    @Transactional(readOnly = true)
    public boolean archived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Archive the sheet; refused when it already is. */
    @Transactional
    public Sheet archive(String id, String user) {
        Sheet sheet = lock(id);
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is already archived.");
        }
        sheet.setArchived(true);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /** The sheet's clerk limit; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return load(id).getClerkLimit();
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
    }

    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
        return setDated(id, user, Sheet.CAP, money(cap), from, true);
    }

    /** Record the sheet's proof threshold (null: none) from a date, auditing the change. */
    @Transactional
    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
        return setDated(id, user, Sheet.PROOF_THRESHOLD, money(threshold), from, false);
    }

    /** Record a grade's proof threshold (null: none, the sheet's applies) from a date, auditing the change. */
    @Transactional
    public Sheet setGradeProofThreshold(String id, String user, String grade, BigDecimal threshold, LocalDate from) {
        return setDated(id, user, Sheet.gradeProofThresholdKey(grade), money(threshold), from, false);
    }

    /** Record the sheet's note threshold (null: none) from a date, auditing the change. */
    @Transactional
    public Sheet setNoteThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
        return setDated(id, user, Sheet.NOTE_THRESHOLD, money(threshold), from, false);
    }

    /** Record the sheet's floor from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        return setDated(id, user, Sheet.FLOOR, money(floor), from, true);
    }

    /** Record the sheet's terms, in days, from a date, auditing the change; claims keep their due-by. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, true);
    }

    /**
     * Record a grade's own terms, in days (null: the sheet's terms), from a date, auditing the change.
     * Claims keep their due-by.
     */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return setDated(id, user, Sheet.gradeTermsKey(grade), terms == null ? null : terms.toString(), from, true);
    }

    /**
     * Record a grade's grace, in days (null: none), from a date, auditing the change and the figures it
     * moves. Claims keep their due-by.
     */
    @Transactional
    public Sheet setGradeGrace(String id, String user, String grade, Integer days, LocalDate from) {
        return setDated(id, user, Sheet.gradeGraceKey(grade), days == null ? null : days.toString(), from, true);
    }

    /** Record the sheet's late percent from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        return setDated(id, user, Sheet.LATE_PCT, money(latePct), from, true);
    }

    /**
     * Record a dated setting's value (null: none) from a date, the sheet's today when none is given,
     * replacing any value recorded from that date. The change is audited, with the from-date when one
     * was given, and so are the figures it moves when it can move any.
     */
    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = movesFigures ? rollups.take(id) : null;
        sheet.record(key, from == null ? sheet.getToday() : from, value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollups.audit(id, user, before);
        }
        return saved;
    }

    /** A figure with two decimals as text; null stays null. */
    private static String money(BigDecimal value) {
        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }

    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = lock(id);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
        return saved;
    }

    /** Change the sheet's entry date (null: off), auditing the change. */
    @Transactional
    public Sheet setEntryDate(String id, String user, LocalDate entryDate) {
        Sheet sheet = lock(id);
        sheet.setEntryDate(entryDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=entry-date value="
                + (saved.getEntryDate() == null ? "" : saved.getEntryDate().toString()));
        return saved;
    }

    /** Change the sheet's grace days (null: off), auditing the change. */
    @Transactional
    public Sheet setGraceDays(String id, String user, Integer graceDays) {
        Sheet sheet = lock(id);
        sheet.setGraceDays(graceDays);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=grace-days value="
                + (saved.getGraceDays() == null ? "" : saved.getGraceDays().toString()));
        return saved;
    }

    /** Set the roles that may take an action (null: the standing rule), auditing the change. */
    @Transactional
    public Sheet setPermission(String id, String user, String action, String roles) {
        Sheet sheet = lock(id);
        sheet.setPermission(action, roles);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value="
                + (roles == null ? "" : roles));
        return saved;
    }
}
package net.officefloor.hq.app.sheet;


@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** What the screen is told about a loaded sheet. */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct, LocalDate policyDate,
            String cap, List<DatedValue> floorHistory, List<DatedValue> latePctHistory, boolean archived,
            Map<String, List<DatedValue>> graceHistory, Integer lastSettleBatch) {

        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    DatedValue.of(sheet.floorHistory()), DatedValue.of(sheet.latePctHistory()), sheet.isArchived(),
                    graceHistory(sheet), sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch());
        }

        /** Each grade's grace values by from-date, its starting value (none) first. */
        static Map<String, List<DatedValue>> graceHistory(Sheet sheet) {
            Map<String, List<DatedValue>> all = new TreeMap<>();
            for (String grade : GRADES) {
                all.put(grade, DatedValue.of(sheet.gradeGraceHistory(grade)));
            }
            return all;
        }
    }

    /** The grades a person can have. */
    static final List<String> GRADES = List.of("A", "B", "C");

    /** A change to the sheet's today. */
    public record TodayChange(@NotNull LocalDate today) {
    }

    /** What the screen is told about the sheet's settings, each dated one as in force on the sheet's today
     * (with the floor's and the late percent's values by from-date): the clerk limit with two decimals, null for none,
     * the floor with two decimals, the terms in days, the late percent with two decimals, and the policy
     * date, null for none (the sheet's today), and the period-numbering-from date, null for none (off), and the grace days, null for none (off), and
     * each grade's own terms in days, null for none (the sheet's terms), and the cap with two decimals, null
     * for none, and the proof threshold with two decimals, null for none, and the note threshold with two
     * decimals, null for none, and the entry date, null for none (off), and each grade's grace in days,
     * null for none, with each grade's grace values by from-date, and each grade's proof threshold with two
     * decimals, null for none (the sheet's applies). */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, Integer graceDays, Integer termsA, Integer termsB, Integer termsC, String cap,
            List<DatedValue> floorHistory, List<DatedValue> latePctHistory, String proofThreshold,
            Map<String, String> permissions, String noteThreshold, LocalDate entryDate, Integer graceA, Integer graceB,
            Integer graceC, Map<String, List<DatedValue>> graceHistory, Map<String, String> gradeProofThresholds) {

        static SettingsView of(Sheet sheet) {
            return new SettingsView(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getLatePct().toPlainString(),
                    sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(), sheet.getGradeTerms("A"),
                    sheet.getGradeTerms("B"), sheet.getGradeTerms("C"),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    DatedValue.of(sheet.floorHistory()), DatedValue.of(sheet.latePctHistory()),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    permissions(sheet),
                    sheet.getNoteThreshold() == null ? null : sheet.getNoteThreshold().toPlainString(),
                    sheet.getEntryDate(), sheet.getGradeGrace("A"), sheet.getGradeGrace("B"), sheet.getGradeGrace("C"),
                    SheetView.graceHistory(sheet), gradeProofThresholds(sheet));
        }

        /** Each grade's proof threshold in force with two decimals; null when it has none (the sheet's applies). */
        private static Map<String, String> gradeProofThresholds(Sheet sheet) {
            Map<String, String> all = new TreeMap<>();
            for (String grade : GRADES) {
                BigDecimal threshold = sheet.getGradeProofThreshold(grade);
                all.put(grade, threshold == null ? null : threshold.toPlainString());
            }
            return all;
        }

        /** The roles set for each action of the permission matrix; blank when it keeps its standing rule. */
        private static Map<String, String> permissions(Sheet sheet) {
            Map<String, String> all = new TreeMap<>();
            Sheet.STANDING_PERMISSIONS.keySet().forEach(action -> {
                String roles = sheet.getPermission(action);
                all.put(action, roles == null ? "" : roles);
            });
            return all;
        }
    }

    /** A setting's value as entered: up to two decimals, or blank (or null) for none. */
    public record SettingChange(@Pattern(regexp = "\\s*(\\d{1,12}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** Grace days as entered: a whole number of days, or blank (or null) for off. */
    public record GraceDaysChange(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value) {

        /** The days entered; null when blank. */
        Integer days() {
            String text = value == null ? "" : value.trim();
            return text.isEmpty() ? null : Integer.valueOf(text);
        }
    }

    /** The roles that may take an action as entered: clerk or steward, comma separated, or blank for the standing rule. */
    public record PermissionChange(
            @Size(max = 64) @Pattern(regexp = "\\s*((clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?") String value) {

        /** The roles entered, each once, comma separated; null when blank. */
        String roles() {
            String text = value == null ? "" : value.trim();
            return text.isEmpty() ? null
                    : String.join(",", Arrays.stream(text.split(",")).map(String::trim).distinct().toList());
        }
    }

    /** A floor as entered: up to two decimals; it cannot be blank. */
    public record FloorChange(@NotNull @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** Terms as entered: a whole number of days; they cannot be blank. */
    public record TermsChange(@NotNull @Pattern(regexp = "\\s*\\d{1,4}\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** A grade's terms as entered: a whole number of days, or blank (or null) for the sheet's terms. */
    public record GradeTermsChange(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** A grade's grace as entered: a whole number of days, or blank (or null) for none. */
    public record GradeGraceChange(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** A late percent as entered: 0.00 or more, up to two decimals; it cannot be blank. */
    public record LatePctChange(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) implements Dated {
    }

    /** A change to a dated setting: from a date entered as yyyy-mm-dd, or blank (or null) for the sheet's today. */
    interface Dated {

        String from();

        /** The from-date entered; null when blank. */
        default LocalDate fromDate() {
            return parse(from());
        }
    }

    /** A setting's value from a date: from null for its starting value, before every from-date. */
    public record DatedValue(LocalDate from, String value) {

        static List<DatedValue> of(List<DatedSetting> history) {
            return history.stream().map(d -> new DatedValue(d.getFromDate(), d.getValue())).toList();
        }
    }

    /** A date as entered; null when blank. */
    static LocalDate parse(String value) {
        String text = value == null ? "" : value.trim();
        try {
            return text.isEmpty() ? null : LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + text);
        }
    }

    /** A date setting as entered: yyyy-mm-dd, or blank (or null) for none. */
    public record DateChange(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {

        /** The date entered; null when blank. */
        LocalDate date() {
            return parse(value);
        }
    }

